<?php require __DIR__.'/bootstrap.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);if($a==='add'){$name=trim((string)($_POST['area_name']??''));if($name!=='')$pdo->prepare('INSERT INTO service_areas(area_name,sort_order,active) VALUES(?,?,1)')->execute([$name,(int)($_POST['sort_order']??0)]);}elseif($a==='delete'&&$id)$pdo->prepare('DELETE FROM service_areas WHERE id=?')->execute([$id]);flash('success','Service areas updated.');header('Location: areas.php');exit;}$rows=$pdo->query('SELECT * FROM service_areas ORDER BY sort_order,id')->fetchAll();$pageTitle='Service Areas';$active='areas';require __DIR__.'/_header.php';?><p class="eyebrow">SERVICE AREAS</p><h1>Coverage locations</h1><section class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add"><div class="two-col"><label>Area / City / ZIP<input name="area_name" required></label><label>Order<input type="number" name="sort_order" value="0"></label></div><button>Add area</button></form></section><div class="table-wrap"><table class="admin-table"><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['area_name'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/_footer.php';
